{
  "id": "R2",
  "summary_ko": "남자가 다른 와인잔을 쥐고 있으나 와인을 집을 때 실제 쥐고 있지 않은 잔을 집어 올리는 모습이 나타남",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "The man is holding a different glass of wine but when he picks up the wine it shows him picking up the one he isn't actually holding",
      "symptom_ko": "남자가 쥐고 있는 와인잔과 집어 올리는 와인잔이 일치하지 않고 실제로 잡고 있지 않은 잔을 들어 올림",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "glass of wine",
      "explicit_detail_evidence": [
        "holding a different glass of wine",
        "picking up the one he isn't actually holding"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R3",
  "summary_ko": "오른쪽에 있는 여성의 의자가 제대로 연결되지 않고 등받이가 공중에 떠 있음",
  "claims": [
